use vstd::prelude::*;

verus! {

fn reverse(a: &Vec<char>) -> (b: Vec<char>)
    requires
        // input must be non‐empty
        a.len() > 0,
    ensures
        // output has same length as input
        b.len() == a.len(),
        // for every valid index i, b[i] = a[n - 1 - i]
        forall |i: usize| i < a.len() ==> b[i] == a[a.len() - 1 - i],
{
    let n: usize = a.len();
    let mut b: Vec<char> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            // i never exceeds n
            i <= n,
            // b has been filled exactly up to index i
            b.len() == i,
            // for all filled indices j < i, b[j] = a[n - 1 - j]
            forall |j: usize| j < i ==> b[j] == a[n - 1 - j],
        decreases n - i,
    {
        // safe because i < n
        let ch = a[n - 1 - i];
        b.push(ch);
        i += 1;
    }
    b
}

} // end of verus! block

